pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound amounts to reasonable values
        depositAmount = bound(depositAmount, 0, 100 ether);
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);

        // Ensure actor is not zero address
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Fund actor and make a deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Attempt withdrawal of the specified amount
        vm.prank(actor);
        // Since withdrawAll withdraws all credit, we can only do a full withdrawal.
        // The property must hold regardless; the mutant breaks it by allowing repeated full withdrawals.
        try c.withdrawAll() {
            // If withdrawal succeeded, check that actor's credit is zero
            // Access credit via a public getter; credit is a mapping, which has an auto-generated getter
            uint256 remainingCredit = c.credit(actor);
            assertTrue(remainingCredit == 0);
        } catch {
            // If withdrawal failed, the contract should be unchanged; but for the property we just skip.
            // The assertTrue only checks the successful case, which the mutant fails.
        }
    }
}

