import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint88 depositAmount0, uint88 depositAmount1, address depositor, address withdrawer) public {
        vm.assume(depositor != address(0) && withdrawer != address(0) && depositor != withdrawer);
        vm.assume(depositAmount0 > 0);
        vm.assume(depositAmount1 > 0);

        // depositor deposits twice to build non-zero balance
        vm.deal(depositor, uint256(depositAmount0) + depositAmount1);
        vm.startPrank(depositor);
        c.deposit{value: depositAmount0}();
        c.deposit{value: depositAmount1}();
        vm.stopPrank();

        // record contract balance before withdrawal
        uint256 balBefore = address(c).balance;

        // withdrawer performs withdrawal (has 0 credit, so no ether transferred but state changes may still differ)
        vm.prank(withdrawer);
        c.withdrawAll();

        // After withdrawal, with unchanged credit for withdrawer, contract balance must be unchanged (since no credit was withdrawn)
        // The correct version preserves invariant: balBefore == address(c).balance.
        // The mutant missing balance subtraction also holds here trivially, but we need a scenario that triggers the bug.
        // Actually we need a scenario where withdrawal actually sends ether, so let depositor also act as withdrawer in a second step.
        // Simpler: let the same user deposit and withdraw.
        // Redesign: single user fuzzed amount.
    }
}

