pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 depositAmount) public {
        // actor may be zero address, but that's fine; depositAmount must be >0 to give actor non-zero credit,
        // which ensures that when we later try withdrawAll after resetting credit to zero,
        // the branch condition 0 > 0 is false (reference) vs 0 >= 0 is true (mutant).
        vm.assume(depositAmount > 0);
        vm.assume(actor != address(0)); // avoid precompile that may revert on value transfer
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Now actor has positive credit. We withdrawAll for another address (msg.sender remains this test contract)
        // The test contract has zero credit. For the reference, 0 > 0 is false, balance unchanged.
        // For the mutant, 0 >= 0 is true, it will attempt to subtract 0 from balance and send 0 ETH.
        uint256 balanceBefore = address(c).balance;
        c.withdrawAll();
        uint256 balanceAfter = address(c).balance;

        // General rule: after a call to withdrawAll by an address with zero credit,
        // the contract's ETH balance MUST NOT be reduced.
        assertTrue(balanceAfter == balanceBefore);
    }
}

