pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 depositAmount, uint128 withdrawAmount) public {
        // 1. Keep depositAmount > 0 to avoid trivial zero-credit path; bound actor to a fresh address
        vm.assume(depositAmount > 0);
        address actor = makeAddr("reenter");
        // 2. Deposit the fuzzed amount first so there is credit to withdraw
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();
        // 3. Record balance before withdrawal
        uint256 balBefore = address(c).balance;
        // 4. Make the withdrawal; capture revert status
        bool ok;
        vm.prank(actor);
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        // 5. Assert universal invariant: if the call succeeded, the contract's balance decreased by exactly the caller's credit
        assertTrue(!ok || address(c).balance == balBefore - depositAmount);
    }
}

