pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 amount, uint128 reenterDepth) public {
        // Ensure at least 1 wei deposited and at most 2 reentrant loops
        uint256 depositAmount = uint256(amount);
        vm.assume(depositAmount > 0);
        uint256 depth = uint256(reenterDepth) % 2; // 0 or 1 extra reentrant call

        // Deploy a reentrant attacker that reenters withdrawAll `depth` times
        ReentrantAttacker attacker = new ReentrantAttacker(c, depth);

        // Fund the attacker and deposit into c
        vm.deal(address(attacker), depositAmount);
        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        // Trigger withdrawal (which may reenter)
        vm.prank(address(attacker));
        attacker.attack();

        // General rule: after all calls settle, credit of the attacker must be zero in the reference version.
        // In the buggy version, reentrancy can leave credit > 0 because balance is subtracted after the call,
        // allowing the outer call to succeed again even though ether was already sent.
        uint256 finalCredit = c.credit(address(attacker));
        assertTrue(finalCredit == 0);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public reentrancyCount;
    uint256 public maxReentrancy;

    constructor(C _target, uint256 _max) {
        target = _target;
        maxReentrancy = _max;
    }

    function attack() external {
        target.withdrawAll();
    }

    receive() external payable {
        if (reentrancyCount < maxReentrancy) {
            reentrancyCount++;
            target.withdrawAll();
        }
    }
}

