pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint112 depositAmount) public {
        // Attacker will reenter during withdrawAll
        address attacker = address(new Attacker(c));
        vm.assume(depositAmount > 0);
        vm.deal(attacker, depositAmount);
        vm.prank(attacker);
        c.deposit{value: depositAmount}();

        uint256 balBefore = address(c).balance;
        vm.prank(attacker);
        c.withdrawAll();
        uint256 balAfter = address(c).balance;

        // The reference contract always ends with balance reduced by exactly depositAmount.
        // The bug allows reentrant withdrawAll to drain more than the single credit,
        // so the contract balance after withdrawal will be less than balBefore - depositAmount.
        assertTrue(balBefore - depositAmount <= balAfter);
    }
}

contract Attacker {
    C target;
    bool reentered;
    constructor(C _target) { target = _target; }
    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.withdrawAll();
        }
    }
}

